ad - ',forms)</l5><l6>when event_onformload ='F' and event_onreportload ='T' then concat('OnReportLoad - ',reports)</l6><l7>end eventdtl,</l7><l8>case when isconstant='T' then concat('Constant: ',vpvalue) </l8><l9>when isvariable='T' then concat('Var: ','&lt;/br&gt;',vscript ) </l9><l10>when isdbobj='T' then concat('DBVar: ','&lt;/br&gt;','DBfun=',db_funtion,case when db_funtion_params is not null then concat('&lt;/br&gt;','DBfunparam=',db_funtion_params) end) </l10><l11>when isappparam ='T' then concat('VPname: ',axvarname,'&lt;/br&gt;','Vartype: ',case when isparam='T' then 'Parameter' else 'Variable' end) end vardtl,</l11><l12>concat('t',stransid) stransid</l12><l13> from axvarcore a </l13><l14>order by 3,1</l14></a2><a3></a3><a4>reportsql</a4></row1></root>$q169914$, $q169915$1$q169915$, $q169916$23-01-2025 12:02:36$q169916$, $q169917$20/09/2022 11:39:45$q169917$, $q169918$26-06-2025 14:39:46$q169918$, $q169919$admin$q169919$, $q169920$admin$q169920$, $q169921$admin$q169921$, NULL, NULL);
