) then '&lt;span style="font-weight:bold;"&gt;'||'Criteria'||'&lt;/span&gt;&lt;br/&gt;' || a.formula || '&lt;br/&gt;' end criteria, </l8><l9>'&lt;b&gt;Created by &lt;/b&gt;'||a.createdby||' on '||a.createdon created,</l9><l10>'&lt;b&gt; Last modified by &lt;/b&gt;'||a.username||' on '||a.modifiedon updated</l10><l11>from axpdef_ruleeng a</l11><l12>where (a.stransid = :ptransid or 'All' = :ptransid)</l12><l13>ORDER BY a.rulename </l13></a2><a3></a3><a4>reportsql</a4></row1><ptransid cat="params" ord="1"><a1>Task1</a1><a0>ptransid</a0><a2>ptransid</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56>All</a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></ptransid><axpdef_ruleengid cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>axpdef_ruleengid</a2><a3>axpdef_ruleengid</a3><a1>Task1</a1><a4>Numeric</a4><a5>0</a5><a6></a6><a7>false</a7><a8>false</a8><a21>true</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>false</a16><a17>175</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></axpdef_ruleengid><form cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>form</a2><a3>Form</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>255</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></form><rulename cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>rulename</a2><a3>Rule Name</a3><a1>Task1</a1><a4>Character