><l25>                   WHEN transid IS NOT NULL THEN 'Document'</l25><l26>                   ELSE 'Alert'</l26><l27>                END) = :petype)</l27><l28>         AND mailto IS NOT NULL</l28><l29>         AND subject IS NOT NULL</l29><l30>         AND mailto &lt;&gt; ''</l30><l31>         AND subject &lt;&gt; ''</l31><l32>ORDER BY jobid</l32></a2><a3></a3><a4>reportsql</a4></row1><asondate cat="params" ord="1"><a1>Task1</a1><a0>asondate</a0><a2>As on Date</a2><a4>Date/Time</a4><a9>False</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11>select date(current_date) sysdt from dual</a11><a5>0</a5><a12>False</a12><a14>False</a14><a56></a56><a13>Accept</a13><a15/><a67>325</a67><a68>false</a68></asondate><psubject cat="params" ord="2"><a1>Task1</a1><a0>psubject</a0><a2>Subject Contains</a2><a4>Character</a4><a9>False</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>False</a12><a14>False</a14><a56>ALL</a56><a13>Accept</a13><a15/></psubject><pstatus cat="params" ord="3"><a1>Task1</a1><a0>pstatus</a0><a2>Status</a2><a4>Character</a4><a9>False</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11>select 'PENDING' status from dual 
union all 
select 'SUCCESS' status from dual 
union all 
select 'FAILURE' status from dual 
union all 
select 'ALL' STATUS from dual
  order by 1</a11><a5>0</a5><a12>False</a12><a14>False</a14><a56></a56><a13>Select</a13><a15/></pstatus><petype cat="params" ord="4"><a1>Task1</a1><a0>petype</a0><a2>Email Type</a2><a4>Character</a4><a9>False</a9><a6 sugg="false">{Alert}</a6><a10></a10><a21>false</a21><a11>select 'Report' etype from dual 
union all 
select 'Document' etype from dual 
union all 
