union 
select 'Failed' pstatus from dual
order by pstatus</a11><a5>0</a5><a12>False</a12><a14>False</a14><a56></a56><a13>Accept</a13><a15/></pstatus><ptransid cat="params" ord="3"><a1>Task1</a1><a0>ptransid</a0><a2>Transid</a2><a4>Character</a4><a9>False</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>False</a12><a14>False</a14><a56>ALL</a56><a13>Accept</a13><a15/></ptransid><pfilename cat="params" ord="4"><a1>Task1</a1><a0>pfilename</a0><a2>File Name</a2><a4>Character</a4><a9>False</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>False</a12><a14>False</a14><a56>ALL</a56><a13>Accept</a13><a15/></pfilename><row1 cat="sql"><a1>Task1</a1><a2><l0>  SELECT filename,</l0><l1>         recdon,</l1><l2>         transid,</l2><l3>         tstructname,</l3><l4>         instatus</l4><l5>    FROM ax_inbound_status</l5><l6>   WHERE indate = :asondt</l6><l7>         AND ( (instatus NOT LIKE '%No of Records not imported : 0%'</l7><l8>                AND :pstatus = 'Failed')</l8><l9>              OR :pstatus = 'ALL')</l9><l10>         AND (transid LIKE '%' || :ptransid || '%' OR :ptransid = 'ALL')</l10><l11>         AND (filename LIKE '%' || :pfilename || '%' OR :pfilename = 'ALL')</l11><l12>ORDER BY recdon DESC</l12></a2><a3></a3><a4>reportsql</a4></row1></root>$q170487$, $q170488$1$q170488$, $q170489$19/06/2019 00:00:00$q170489$, $q170490$02/07/2015 00:00:00$q170490$, $q170491$26-06-2025 14:40:37$q170491$, $q170492$admin$q170492$, $q170493$admin$q170493$, $q170494$admin$q170494$, NULL, NULL);
