p="addrule" type="iview" apply="" applyon="" sname="ad___fpr" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="2"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>LoadForm({a__re},{formcaption=:fcap},{p},{t})</l0></exprset></param1></r1></addrule><aprn script="true" cap="autoprint" type="iview" apply="" applyon="" sname="ad___fpr" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="2"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>LoadForm({a__ap},{form=:fcap},{p},{t})</l0></exprset></param1></r1></aprn><formnotify script="true" cap="formnotify" type="iview" apply="" applyon="" sname="ad___fpr" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="2"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>LoadForm({a__fn},{form=:fcap},{p},{t})</l0></exprset></param1></r1></formnotify><fastprt script="true" cap="fastprt" type="iview" apply="" applyon="" sname="ad___fpr" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="2"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>LoadForm({ad_fp},{form_caption=:fcap},{p},{t})</l0></exprset></param1></r1></fastprt></scripts><comps cat="comps" dwbtb="true" LocalNum="9" btn="4" vupd="" pnlheight="35"><btn1 key="btn9" caption="Add Rule" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="" action="addrule" script="true" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Add Rule" down=""><icon><text>verified_user</text><addClass>material-icons</addClass></icon></btn1><btn2 key="btn10" caption="Add Form notification" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="" action="formnotify" script="true" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Add Form notification" down=""><icon><text>circle_notifications</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn12" caption="Add Auto print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="" action="aprn" script="true" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Add Auto print" down=""><icon><text>local_printshop</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btnTask" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="false" footer="false" folder="true" hint="Tasks" down=""><icon><text>fact_check</text><addClass>material-icons</addClass></icon></btn4><x__head caption="Form components" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select null editable,'DC' ctypre,a.name ntransid, a.caption fcaption, b.dname cname,concat(b.caption,'(',b.dname,')') ccaption, </l0><l1>concat('&lt;span style="font-weight:bold;"&gt;','Caption - ','&lt;/span&gt;' , concat(b.caption,'-(',b.dname,')'), '&lt;br/&gt;' ,</l1><l2>case when b.asgrid = 'T' then '(Grid DC)' else ' ' end,</l2><l3>'&lt;span style="font-weight:bold;"&gt;','Saving to Table ','&lt;/span&gt;', b.tablename,'&lt;br/&gt;') as cprops,NULL datarule,NULL validrule,b.dname,</l3><l4>b.dcno ordno,1 lord,null editcmd,a.caption||'-('||a.name||')' fparams,</l4><l5>'&lt;b&gt;Created by&lt;/b&gt; '||b.createdby||' on '||b.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||b.modifiedby||' on '||b.modifiedon updated,</l5><l6>null editcmdtransid,0 editcmdrecid</l6><l7>from tstructs a join  axpdc b on b.tstruct = a.name </l7><l8>where a.name = :ptransid </l8><l9>union all</l9><l10>select runtimefld editable,'Field' ctypre,a.name, a.caption, c.fname cname, concat(c.caption,'(',c.fname,')')  ccaption, </l10><l11>concat('&lt;span style="font-weight:bold;"&gt;',</l11><l12>case when c.runtimefld ='T' then 'Runtime' else 'Developer' end|| '&lt;br/&gt;','Field type - ','&lt;/span&gt;', c.customdatatype,'&lt;br/&gt;',</l12><l13>'&lt;span style="font-weight:bold;"&gt;'||'Data type and Width - ','&lt;/span&gt;',concat(case "datatype" when 'c' then 'Character'  </l13><l14>when 'd' then 'Date' when 'i' then 'Image' when 't' then 'Text' when 'n' then 'Numeric' end,'(',case when datatype='n' </l14><l15>then concat(cast(datawidth as varchar(5)),',',cast(flddecimal as varchar(5))) else cast(datawidth  as varchar(10)) end,')' ),'&lt;br/&gt;') fdesc,</l15><l16>concat(coalesce(case when c.readonly = 'T' then  '&lt;span style="font-weight:bold;"&gt;'||'ReadOnly '||'&lt;/span&gt;&lt;br/&gt;' || ''|| '&lt;br/&gt;' end,''),</l16><l17>coalesce(case when c.hidden= 'T' then '&lt;span style="font-weight:bold;"&gt;'||'Hidden'||'&lt;/span&gt;&lt;br/&gt;' ||''|| '&lt;br/&gt;' end,''),</l17><l18>coalesce('&lt;span style="font-weight:bold;"&gt;'||case when c.allowempty= 'F' then 'Mandatory' else '' end||'&lt;/span&gt;&lt;br/&gt;' ||''|| '&lt;br/&gt;' ,''),</l18><l19>coalesce(case when c.mask is not null then '&lt;span style="font-weight:bold;"&gt;'||'Mask '||'&lt;/span&gt;&lt;br/&gt;'|| c.mask||' &lt;br/&gt;' end,''),</l19><l20>coalesce('&lt;span style="font-weight:bold;"&gt;'||case when c.allowduplicate= 'F' then 'Unique'||'&lt;/span&gt;&lt;br/&gt;' ||''|| '&lt;br/&gt;' end ,'')</l20><l21>) datarule,</l21><l22>concat(coalesce(case when c.expression is not null then '&lt;span style="font-weight:bold;"&gt;'||'Expression '||'&lt;/span&gt;&lt;br/&gt;' || c.expression || '&lt;br/&gt;' end,''),</l22><l23>coalesce(case when c.valexpr is not null then '&lt;span style="font-weight:bold;"&gt;'||'Validation  '||'&lt;/span&gt;&lt;br/&gt;' || c.valexpr || '&lt;br/&gt;' end,' ')) validrule,</l23><l24>c.dcname,c.ordno,2 lord,null editcmd,a.caption||'-('||a.name||')' fparams,</l24><l25>'&lt;b&gt;Created by&lt;/b&gt; '||c.createdby||' on '||c.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||c.modifiedby||' on '||c.modifiedon updated,null editcmdtransid,0 editcmdrecid</l25><l26>from tstructs a </l26><l27>join axpflds c on a.name = c.tstruct  </l27><l28>where a.name = :ptransid </l28><l29>union all</l29><l30>select null editable,'Fillgrid' ctypre,t.name,t.caption, a.fgname,concat(a.caption,'(',a.fgname,')'),</l30><l31>concat('&lt;span style="font-weight:bold;"&gt;','Target DC - ','&lt;/span&gt;' , 'dc'||tardc, '&lt;br/&gt;' ,</l31><l32>'&lt;span style="font-weight:bold;"&gt;','Data source - ','&lt;/span&gt;', case when a.srcdc = '0' then 'SQL' else 'dc'||a.srcdc end,'&lt;br/&gt;',</l32><l33>'&lt;span style="font-weight:bold;"&gt;','Autoshow - ','&lt;/span&gt;', case when a.autoshow = 'T' then 'Yes' else 'No' end, '&lt;br/&gt;',</l33><l34>'&lt;span style="font-weight:bold;"&gt;','Multiselect - ','&lt;/span&gt;', case when a.multiselect = 'T' then 'Yes' else 'No' end, '&lt;br/&gt;'</l34><l35>) as cprops,null,null,'z100',1,3,null editcmd,t.caption||'-('||t.name||')' fparams,</l35><l36>'&lt;b&gt;Created by&lt;/b&gt; '||a.createdby||' on '||a.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||a.modifiedby||' on '||a.modifiedon updated,null editcmdtransid,0 editcmdrecid</l36><l37>from axpfillgrid a join tstructs t on a.tstruct =t.name  and t.name = :ptransid</l37><l38>union all</l38><l39>select null editable,'MDMAP' ctypre,t.name,t.caption, a.mname,concat(a.caption,'(',a.mname,')'),</l39><l40> concat('&lt;span style="font-weight:bold;"&gt;','Master form - ','&lt;/span&gt;' , mt.caption||'-('||mt."name"||')' , '&lt;br/&gt;' ,</l40><l41>'&lt;span style="font-weight:bold;"&gt;','Master field - ','&lt;/span&gt;',muf.caption||'-('||muf.fname||')' ,'&lt;br/&gt;',</l41><l42>'&lt;span style="font-weight:bold;"&gt;','Detail field - ','&lt;/span&gt;',duf.caption||'-('||duf.fname||')' ,'&lt;br/&gt;',</l42><l43>'&lt;span style="font-weight:bold;"&gt;','Master search field -  ','&lt;/span&gt;',CASE WHEN msf.fname IS NULL THEN 'Default' ELSE  coalesce(msf.caption||'-('||msf.fname||')',a.msrcfld) end, '&lt;br/&gt;',</l43><l44>'&lt;span style="font-weight:bold;"&gt;','Detail search field - ','&lt;/span&gt;',coalesce(dsf.caption||'-('||dsf.fname||')',a.dtlsrcfld)</l44><l45>) as cprops,null,null,'z100',1,4,null editcmd,t.caption||'-('||t.name||')' fparams,</l45><l46>'&lt;b&gt;Created by&lt;/b&gt; '||a.createdby||' on '||a.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||a.modifiedby||' on '||a.modifiedon updated,null editcmdtransid,0 editcmdrecid</l46><l47>from axpmdmaps a join tstructs t on a.tstruct =t.name and t.name = :ptransid</l47><l48>join tstructs mt on a.mastrans = mt.name</l48><l49>join axpflds muf on a.masfld = muf.fname and a.mastrans = muf.tstruct </l49><l50>left join axpflds msf on a.msrcfld = msf.fname and a.mastrans = msf.tstruct </l50><l51>join axpflds duf on a.detfld = duf.fname and a.tstruct = duf.tstruct</l51><l52>left join axpflds dsf on a.dtlsrcfld = dsf.fname and a.tstruct = dsf.tstruct</l52><l53>union all</l53><l54>select null editable,'Genmap',t.name,t.caption fcaption, a.gname,concat(a.caption,'(',a.gname,')'),</l54><l55>concat('&lt;span style="font-weight:bold;"&gt;','Target form - ','&lt;/span&gt;' , tt.caption||'-('||tt.name||')', '&lt;br/&gt;' ,</l55><l56>'&lt;span style="font-weight:bold;"&gt;','Based on - ','&lt;/span&gt;', basedondc,'&lt;br/&gt;',</l56><l57>'&lt;span style="font-weight:bold;"&gt;','Control fieldname','&lt;/span&gt;', a.ctrlfldname , '&lt;br/&gt;') as cprops,null,null,'z100',1,5,null editcmd,</l57><l58>t.caption||'-('||t.name||')' fparams,</l58><l59>'&lt;b&gt;Created by&lt;/b&gt; '||a.createdby||' on '||a.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||a.modifiedby||' on '||a.modifiedon updated,</l59><l60>null editcmdtransid,0 editcmdrecid</l60><l61>from axpgenmaps a join tstructs t on a.tstruct =t.name  and t.name = :ptransid</l61><l62>join tstructs tt on a.targettstr = tt.name</l62><l63>union all</l63><l64>SELECT null editable,'Script',t.name,t.caption,a.name,a.caption||'('||a.name||')',</l64><l65>'&lt;span style="font-weight:bold;"&gt;'||'Form control - '||'&lt;/span&gt;' || 'dc'||control_type || '&lt;br/&gt;' ||</l65><l66>'&lt;span style="font-weight:bold;"&gt;'||'Script - '||'&lt;/span&gt;' || 'dc'||a.script|| '&lt;br/&gt;' ||</l66><l67>'&lt;span style="font-weight:bold;"&gt;'||'Event - '||'&lt;/span&gt;' || 'dc'||"event" || '&lt;br/&gt;',NULL,NULL,</l67><l68>'z100',1,6,t.caption||'-('||t.name||')' fparams,null editcmd,</l68><l69>'&lt;b&gt;Created by &lt;/b&gt;'||a.createdby||' on '||a.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||a.username||' on '||a.modifiedon updated,</l69><l70>null editcmdtransid,0 editcmdrecid</l70><l71>FROM tstructSCRIPTs a join tstructs t on a.name =t.name and t.name = :ptransid</l71><l72>union all</l72><l73>select null editable,'Rule',t.name,t.caption,rulename,rulename,  </l73><l74>concat('&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Applicable Userroles - &lt;/b&gt;','&lt;/span&gt;',uroles,'&lt;br/&gt;',</l74><l75>'&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;',case when a.readonly ='T' then 'ReadOnly' else 'Editable' end,'&lt;/b&gt;&lt;/span&gt;&lt;br/&gt;',</l75><l76>'&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Cached save - &lt;/b&gt;','&lt;/span&gt;',case when a.cachedsave='T' then 'Yes' else 'No' end ,'&lt;br/&gt;',</l76><l77>'&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;',case when active='T' then 'Active' else 'Inactive' end,'&lt;/b&gt;&lt;/span&gt;&lt;br/&gt;') props,null,null,'z100',1,7,</l77><l78>'&lt;a title ="editi" href="tstruct.aspx?transid=ad_re&amp;act=load&amp;axpdef_ruleengid=' || a.axpdef_ruleengid || '" style="cursor: pointer;"&gt;&lt;span class="material-icons "&gt;edit&lt;/span&gt; &lt;/a&gt;' cmd,</l78><l79>t.caption||'-('||t.name||')' fparams,</l79><l80>'&lt;b&gt;Created by&lt;/b&gt; '||a.createdby||' on '||a.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||a.username||' on '||a.modifiedon updated,'tad_re' editcmdtransid,axpdef_ruleengid editcmdrecid</l80><l81>from axpdef_ruleeng a join tstructs t on a.stransid = t.name and t.name = :ptransid</l81><l82>union all</l82><l83>select null editable,'Auto Print',t.name ntransid,a.cancel, a.autoprintid,a.autoprintid,</l83><l84>concat('&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Form - &lt;/b&gt;','&lt;/span&gt;',form,'&lt;br/&gt;', </l84><l85>'&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Direct Print - &lt;/b&gt;','&lt;/span&gt;',case when directprint = 'T' then 'Yes' else 'No' end,'&lt;br/&gt;',</l85><l86>'&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Fast print - &lt;/b&gt;','&lt;/span&gt;' ,printdoc,'&lt;br/&gt;'),null,null ,'z100',1,9,</l86><l87>'&lt;a title ="editi" href="tstruct.aspx?transid=a__ap&amp;act=load&amp;axautoprintsid=' || a.axautoprintsid || '" style="cursor: pointer;"&gt;&lt;span class="material-icons "&gt;edit&lt;/span&gt; &lt;/a&gt;' cmd</l87><l88>,t.caption||'-('||t.name||')' fparams,</l88><l89>'&lt;b&gt;Created by&lt;/b&gt; '||a.createdby||' on '||a.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||a.username||' on '||a.modifiedon updated,'ta__ap' editcmdtransid,axautoprintsid editcmdrecid</l89><l90>from axautoprints a join tstructs t on a.stransid =t.name and t.name = :ptransid</l90><l91>union all</l91><l92>select null editable,'Form Notification',t.name ntransid,t.caption,a.form,a.form,</l92><l93>concat('&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Notify to - &lt;/b&gt;','&lt;/span&gt;',notifyto,'&lt;br/&gt;','&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;','&lt;/span&gt;',case when active='T' then 'Active' else 'Inactive' end,'&lt;/b&gt;&lt;br/&gt;') props,null,null,'z100',1,10,</l93><l94>'&lt;a title ="editi" href="tstruct.aspx?transid=a__fn&amp;act=load&amp;AxFormNotifyid=' || a.AxFormNotifyid || '" style="cursor: pointer;"&gt;&lt;span class="material-icons "&gt;edit&lt;/span&gt; &lt;/a&gt;' cmd</l94><l95>,t.caption||'-('||t.name||')' fparams,</l95><l96>'&lt;b&gt;Created by&lt;/b&gt; '||a.createdby||' on '||a.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||a.username||' on '||a.modifiedon updated,</l96><l97>'ta__fn' editcmdtransid,AxFormNotifyid editcmdrecid</l97><l98> from   AxFormNotify a join tstructs t on a.stransid =t.name and t.name = :ptransid</l98><l99>union all</l99><l100>select null editable,'Process definition',t.name,t.caption,</l100><l101>'&lt;a title="'||a.TASKNAME||'" href="processflow.aspx?loadcaption=AxProcessBuilder&amp;processname='||a.processname||'" style="cursor: pointer;"&gt;'||a.TASKNAME||'  &lt;/a&gt;'TASKNAME,a.processname , </l101><l102>concat('&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Task type - &lt;/b&gt;','&lt;/span&gt;',tasktype,'&lt;br/&gt;',</l102><l103>'&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Keyfield - &lt;/b&gt;','&lt;/span&gt;',KEYFIELDCAPTION,'&lt;br/&gt;',</l103><l104>'&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Assign to- &lt;/b&gt;','&lt;/span&gt;',ASSIGNTO,'&lt;br/&gt;',</l104><l105>'&lt;span style="font-weight:bold;"&gt;','&lt;b&gt;Keyfield - &lt;/b&gt;','&lt;/span&gt;',KEYFIELDCAPTION,'&lt;br/&gt;') props,</l105><l106>NULL,NULL,'z100',1,11,null editcmd,t.caption||'-('||t.name||')' fparams,</l106><l107>'&lt;b&gt;Created by &lt;/b&gt;'||a.createdby||' on '||a.createdon||'&lt;/br&gt;&lt;b&gt; Last modified by &lt;/b&gt;'||a.username||' on '||a.modifiedon updated,</l107><l108>null editcmdtransid,AXPROCESSDEFV2id editcmdrecid</l108><l109> from   AXPROCESSDEFV2 a join tstructs t on a.transid =t.name and t.name = :ptransid</l109><l110>union all</l110><l111>select null editable,'Outbound queue',t.name ntransid,t.caption, a.axqueuename ,a.axqueuename,</l111><l112>co