 cap="add permission" type="iview" apply="Current Row " applyon="" sname="ad___ups" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="6"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>if axpermissionsid &gt; 0 &amp; stype#{i}</l0><l1>LoadFormAndData({a__up},{axpermissionsid=:axpermissionsid},{d},{false})</l1><l2>elseif axpermissionsid = 0 &amp; stype#{i}</l2><l3>LoadForm({a__up},{axuserrole=:groupname~fromsource=:psource~comptype=:comptype~formcap=:capui},{d},{false})</l3><l4>end</l4></exprset></param1></r1></aperm></scripts><comps cat="comps" dwbtb="true" LocalNum="9" btn="2" vupd="" pnlheight="35"><btn1 key="btn9" caption="New" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="" action="newrec" script="true" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="New" down=""><icon><text>playlist_add</text><addClass>material-icons</addClass></icon></btn1><btn2 key="btnTask" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" folder="true" hint="Tasks" down=""><icon><text>fact_check</text><addClass>material-icons</addClass></icon></btn2><x__head caption="Role permission setup" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select  a.axpermissionsid,b.groupname, coalesce(b.caption,b.sname) formcap,coalesce(a.allowcreate,'Yes') allowcreate,</l0><l1>coalesce(a.viewdlts,'All')viewdlts,coalesce(editdlts,'All') editdlts,</l1><l2>b.sname,concat(b.caption,'-(',b.sname,')') capui,'Form' comptype,b.stype,</l2><l3>case b.stype when 't' then 'Form' when 'i' then 'Report' when 'p' then 'Page' else null end stypeui</l3><l4>from (</l4><l5>select  b.axpermissionsid recordid,b.axpermissionsid,b.axusername ,b.axuserrole ,b.formcap,coalesce(b.allowcreate,'Yes') allowcreate,</l5><l6>	case b.viewctrl when '0' then 'All' </l6><l7>	when '1' then 'View these fields - '||view_flds </l7><l8>	when '2' then 'View exclude these fields - '||view_flds </l8><l9>	when '4' then 'No access' else 'All' end viewdlts,	</l9><l10>	case b.editctrl when '0' then 'All' </l10><l11>	when '1' then 'Edit these fields - '||edit_flds </l11><l12>	when '2' then 'Edit exclude these fields '||edit_flds</l12><l13>	when '4' then 'No access' else 'All' end editdlts ,b.formtransid 	</l13><l14>from  axpermissions b where  b.axuserrole =:prole and 'Form' =b.comptype)a</l14><l15>right join (select distinct sname,caption,groupname,stype from vw_username_role_menu_access where groupname=:prole</l15><l16>and (stype =case :pstype when 'Form' then 't' when 'Report' then 'i' when 'Page' then 'p' end or 'All' = :pstype)) b on </l16><l17>b.sname = a.formtransid </l17><l18>where (case when a.axpermissionsid &gt; 0 then 'Yes' else 'No' end = :pctrl or 'All' = :pctrl)</l18><l19>union all</l19><l20>select a.axpermissionsid,:prole, b.sqlname formcap,'NA' allowcreate,</l20><l21>coalesce(a.viewdlts,'All')viewdlts,'NA' editdlts,</l21><l22>sqlname sname,sqlname capui,'ADS' comptype,'ADS' stype,'ADS' stypeui from</l22><l23>(</l23><l24>select  p.axpermissionsid recordid, p.axpermissionsid,p.axusername,axuserrole groupname, p.formcap,</l24><l25>case p.viewctrl when '0' then 'All' </l25><l26>	when '1' then 'View these fields - '||view_flds </l26><l27>	when '2' then 'View exclude these fields - '||view_flds </l27><l28>	when '4' then 'No access' else 'All' end viewdlts</l28><l29>from axpermissions p </l29><l30>where  p.comptype ='ADS' and p.axuserrole = :prole)a</l30><l31>right join(select sqlname from axdirectsql)b on a.formcap=b.sqlname</l31><l32>where (:pstype ='ADS' or 'All' = :pstype)</l32><l33>and (case when a.axpermissionsid &gt; 0 then 'Yes' else 'No' end = :pctrl or 'All' = :pctrl)</l33><l34>order by 4</l34></a2><a3></a3><a4>reportsql</a4></row1><prole cat="params" ord="1"><a1>Task1</a1><a0>prole</a0><a2>prole</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{All}</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></prole><psource cat="params" ord="2"><a1>Task1</a1><a0>psource</a0><a2>psource</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>false</a12><a14>false</a14><a56>R</a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></psource><pstype cat="params" ord="3"><a1>Task1</a1><a0>pstype</a0><a2>Menu type</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11>select cnd,ord from 
(select 'All' cnd,1 ord from dual
union all
select 'Form' cnd,2 ord from dual
union all
select 'Report' cnd,3 ord from dual
union all
select 'Pages' cnd,4 ord from dual
union all
select 'ADS' cnd,5 ord from dual
)a order by 2 </a11><a5>0</a5><a12>true</a12><a14>false</a14><a56>All</a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pstype><pctrl cat="params" ord="4"><a1>Task1</a1><a0>pctrl</a0><a2>Permission configured</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11>select unnest(string_to_array('Yes,No,All',','))</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56>All</a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pctrl><axpermissionsid cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>axpermissionsid</a2><a3>axpermissionsid</a3><a1>Task1</a1><a4>Numeric</a4><a5>0</a5><a6></a6><a7>false</a7><a8>false</a8><a21>true</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>false</a16><a17>99</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></axpermissionsid><formcap cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>formcap</a2><a3>Menu</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>263</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55>aperm</a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></formcap><stypeui cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>stypeui</a2><a3>Object type</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>80</a17><a18></a18><a19>false</a19><a