INSERT INTO {schema}.iviewsql (iname, scripttext, type, task, blobno, relation_field, cat, sname, ordno) VALUES ($q170754$hplist$q170754$, $q170755$select a1.caption as fromCaption ,case when a1.isacoretrans='No' then 'hidden' when a1.isacoretrans='Yes' and a1.menuposition='Default' then 'root' when a1.isacoretrans='Yes' and a1.menuposition !='Default' and a1.menulist !='' then a1.menulist else 'Not Defined' end as Modulename,  '<b>'|| COALESCE(d.cntimg,'') ||' ' || case when COALESCE(a2.filedtl,'')='' then '' else  COALESCE(a2.filedtl,'') || '</b> Files' end as detail,'<b>' || a1.createdBy || '</b> on ' || a1.createdon as createdBy, '<b>' || a1.username || '</b> on ' || a1.modifiedon as updatedBy ,a1.htmlsectionsid from htmlsections  a1
left join (select string_agg(cnt||' '||filetype ,', ')  as filedtl , htmlsectionsid from 
(select count(filetype) as cnt,filetype,htmlsectionsid from sect4 group by filetype ,htmlsectionsid order by filetype) b
group by b.htmlsectionsid) a2 on a1.htmlsectionsid=a2.htmlsectionsid
left join ( select count(cc)|| ' Image,' as cntimg,htmlsectionsid from ( 
SELECT regexp_split_to_table(axpfile_hpimages, ',') as cc,htmlsectionsid FROM htmlsections where coalesce(axpfile_hpimages,'')<>'') as c
GROUP by htmlsectionsid ) d on a1.htmlsectionsid =d.htmlsectionsid 
order by a1.createdon desc
$q170755$, $q170756$reportsql$q170756$, $q170757$Task1$q170757$, $q170758$1$q170758$, NULL, $q170759$sql$q170759$, $q170760$row1$q170760$, $q170761$1$q170761$);
