INSERT INTO {schema}.iviewsql (iname, scripttext, type, task, blobno, relation_field, cat, sname, ordno) VALUES ($q170834$ad_pgv2$q170834$, $q170835$select concat('<b>Desc:</b> '||c.processdesc,
