INSERT INTO {schema}.iviewsql (iname, scripttext, type, task, blobno, relation_field, cat, sname, ordno) VALUES ($q171754$axemllog$q171754$, $q171755$  SELECT jobid,
         jobdate,
         mailto,
         mailcc,
         subject,
         SUBSTR (body, 1, 80) || '...' AS body,
         senton,
         CASE
            WHEN status = 1 THEN 'Success'
            WHEN status = 0 THEN 'Pending'
            ELSE errormessage
         END
            errormessage
    FROM axp_mailjobs
   WHERE (mailto IS NOT NULL OR mailto <> '') AND jobdate = :asondate
         AND (UPPER (subject) LIKE '%' || UPPER (:psubject) || '%'
              OR UPPER (:psubject) = 'ALL')
         AND ( (CASE
                   WHEN status = 1 THEN 'SUCCESS'
                   WHEN status = 0 THEN 'PENDING'
                   ELSE 'FAILURE'
                END) = UPPER (:pstatus)
              OR UPPER (:pstatus) = 'ALL')
         AND ( (CASE
                   WHEN iviewname IS NOT NULL THEN 'Report'
                   WHEN transid IS NOT NULL THEN 'Document'
                   ELSE 'Alert'
                END) = :petype)
         AND mailto IS NOT NULL
         AND subject IS NOT NULL
         AND mailto <> ''
         AND subject <> ''
ORDER BY jobid
$q171755$, $q171756$reportsql$q171756$, $q171757$Task1$q171757$, $q171758$1$q171758$, NULL, $q171759$sql$q171759$, $q171760$row1$q171760$, $q171761$1$q171761$);
