INSERT INTO {schema}.iviewsql (iname, scripttext, type, task, blobno, relation_field, cat, sname, ordno) VALUES ($q171874$ad___ugp$q171874$, $q171875$select axpdef_usergroupsid,users_group_name,coalesce(b.users,0),
case when au.isactive = 'T' then 
