INSERT INTO {schema}.iviewsql (iname, scripttext, type, task, blobno, relation_field, cat, sname, ordno) VALUES ($q171882$ad___upg$q171882$, $q171883$select b.axgroupingid,a.grpname,b.grpvalue,concat(b.grpparent,'-',pd.grpcaption,'(',pd.grpname,')') parentgrp, a.axgroupingmstid 
from axgroupingmst a 
